from html import escape
from pathlib import Path

THEME = Path(__file__).resolve().parents[1]


def write(path, content):
    target = THEME / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content.strip() + '\n', encoding='utf-8')


def svg(title, body, viewbox='0 0 680 680'):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns:dc="http://purl.org/dc/elements/1.1/" viewBox="{viewbox}" role="img" aria-labelledby="title">
<title id="title">{escape(title)}</title>
<metadata><rdf:RDF><rdf:Description><dc:creator><rdf:Seq><rdf:li>Dhruba Poudel</rdf:li></rdf:Seq></dc:creator><dc:title>{escape(title)}</dc:title><dc:rights>Original illustration by Dhruba Poudel. GPL-2.0-or-later.</dc:rights><lastModifiedBy xmlns="https://about.dhrub.com.np/ns/">Dhruba Poudel</lastModifiedBy></rdf:Description></rdf:RDF></metadata>
{body}
</svg>'''


