def card(product, index):
    name, category, filter_name, filename, price, description, details = map(escape, product)
    return f'''<article class="cc-product-card" data-product-category="{filter_name}"><div class="cc-product-image"><img src="../assets/images/{filename}" alt="Original illustration of the fictional {name}" width="680" height="680" loading="lazy"><span class="cc-product-category">{category} / {index + 1:02d}</span></div><div class="cc-product-heading"><h3>{name}</h3><span class="cc-price">{price} <small>AUD</small></span></div><p class="cc-product-copy">{description}</p><details class="cc-product-details"><summary>Explore {name} details</summary><p>{details}</p><p class="cc-sample-note">Fictional product · Sample price · No checkout</p></details></article>'''


filters = '''<div class="cc-collection-toolbar"><div class="cc-filters" role="group" aria-label="Filter fictional catalogue" data-catalogue-filters hidden><button class="cc-filter" type="button" data-product-filter="all" aria-pressed="true">All objects</button><button class="cc-filter" type="button" data-product-filter="home" aria-pressed="false">For the home</button><button class="cc-filter" type="button" data-product-filter="carry" aria-pressed="false">To carry</button><button class="cc-filter" type="button" data-product-filter="paper" aria-pressed="false">On paper</button></div><p class="cc-product-count" data-product-count aria-live="polite" aria-atomic="true">6 fictional objects</p></div>'''

main = '''<main id="main">
  <section class="cc-hero cc-wrap" aria-labelledby="hero-title"><div class="cc-hero-grid"><div class="cc-hero-copy"><span class="cc-eyebrow">01 / Everyday, considered</span><h1 id="hero-title">A little less.<em>A little better.</em></h1><p class="cc-hero-intro">Useful forms. Warm colours. A quieter everyday. An original storefront design for objects with a simple purpose.</p><a class="cc-button" href="#collection">Explore the collection <span aria-hidden="true">↗</span></a><div class="cc-hero-byline"><span class="cc-byline-mark" aria-hidden="true">DP</span><span>Designed &amp; developed by<strong>Dhruba Poudel</strong></span></div></div><figure class="cc-hero-art"><img src="@@HERO@@" alt="Original illustrated still life of a forest-green cup and terracotta desk lamp" width="900" height="900" fetchpriority="high"><div class="cc-art-badge" aria-hidden="true">Good form<strong>Everyday</strong>Simple purpose</div><figcaption><span>Ridge cup &amp; Loop lamp</span><span>Original illustration study</span></figcaption></figure></div><div class="cc-hero-meta"><p><span class="cc-dot" aria-hidden="true"></span><strong>Commerce Canvas</strong> — an original WordPress theme</p><p>@@HERO_STATUS@@</p></div></section>

  <section class="cc-section cc-wrap" id="collection" aria-labelledby="collection-title"><div class="cc-section-heading"><div><span class="cc-eyebrow">02 / The collection</span><h2 id="collection-title">Small things.<br>Considered details.</h2></div><p>@@CATALOGUE_INTRO@@</p></div>@@FILTERS@@<div class="cc-product-grid" data-product-grid>@@PRODUCTS@@</div><p class="cc-catalogue-note">@@CATALOGUE_NOTE@@</p></section>

  <section class="cc-editorial" id="the-idea" aria-labelledby="idea-title"><div class="cc-wrap cc-editorial-grid"><div class="cc-editorial-copy"><span class="cc-eyebrow">03 / The idea</span><h2 id="idea-title">Good form.<br><em>Useful function.</em></h2><p>A clear hierarchy, room for the product and details that stay out of the way. The design brings together an original visual identity, a responsive theme and a catalogue people can explore at their own pace.</p><a class="cc-editorial-link" href="#theme-notes">Inside the build <span aria-hidden="true">↗</span></a></div><figure class="cc-editorial-art"><img src="@@EDITORIAL@@" alt="Original illustration of a green notebook, loose paper and terracotta bowl" width="900" height="760" loading="lazy"></figure></div></section>

  <section class="cc-section cc-wrap" id="theme-notes" aria-labelledby="notes-title"><div class="cc-section-heading"><div><span class="cc-eyebrow">04 / Craft notes</span><h2 id="notes-title">A store,<br>carefully composed.</h2></div><p>@@BUILD_INTRO@@</p></div><div class="cc-notes-grid"><article class="cc-note"><span class="cc-note-number">01</span><h3>An original identity</h3><p>Cream, forest and terracotta. A geometric mark, editorial type and original vector illustrations form one visual system. System fonts and local assets keep it self-contained.</p></article><article class="cc-note"><span class="cc-note-number">02</span><h3>Designed for the screen</h3><p>The catalogue moves from three columns to two, then one. Native product disclosures, visible focus states, a skip link and reduced-motion support make the small interactions deliberate.</p></article><article class="cc-note"><span class="cc-note-number">03</span><h3>Built for WordPress</h3><p>The classic theme supports custom logos, navigation menus, page content and an optional WooCommerce catalogue. Dynamic product text, URLs and permitted HTML have distinct escaping paths.</p></article></div><div class="cc-preview-status"><span class="cc-status-mark" aria-hidden="true">i</span><p><strong>@@STATUS_TITLE@@</strong>@@STATUS_BODY@@</p></div></section>
</main>'''

