php_main = main.replace('@@HERO@@', "<?php echo esc_url(commerce_canvas_asset('images/hero-still-life.svg')); ?>").replace('@@EDITORIAL@@', "<?php echo esc_url(commerce_canvas_asset('images/editorial-still-life.svg')); ?>").replace('@@HERO_STATUS@@', "<?php echo esc_html($is_sample ? __('Fictional catalogue · No checkout', 'commerce-canvas') : __('Published WooCommerce catalogue', 'commerce-canvas')); ?>").replace('@@CATALOGUE_INTRO@@', "<?php echo esc_html($is_sample ? __('Six fictional objects, illustrated and arranged to demonstrate the theme. Sample prices are shown for layout only.', 'commerce-canvas') : __('Explore the latest visible products from this WooCommerce catalogue.', 'commerce-canvas')); ?>").replace('@@FILTERS@@', '<?php if ($is_sample) : ?>' + filters + '<?php else : ?><div class="cc-collection-toolbar"><p class="cc-product-count"><?php echo esc_html(sprintf(_n(\'%d published product\', \'%d published products\', count($live_products), \'commerce-canvas\'), count($live_products))); ?></p></div><?php endif; ?>').replace('@@PRODUCTS@@', '<?php foreach ($products as $index => $product) { commerce_canvas_product_card($product, (int) $index, $is_sample); } ?>').replace('@@CATALOGUE_NOTE@@', "<?php echo esc_html($is_sample ? __('This is a fictional, read-only catalogue. Products, descriptions and prices are design fixtures; nothing is offered for sale.', 'commerce-canvas') : __('Product details and prices are supplied by WooCommerce. This homepage reads the published catalogue without changing orders or cart contents.', 'commerce-canvas')); ?>").replace('@@BUILD_INTRO@@', 'An original classic theme with a separate static design preview. Catalogue behaviour depends on whether WooCommerce has visible published products.').replace('@@STATUS_TITLE@@', "<?php echo esc_html($is_sample ? __('Sample catalogue mode', 'commerce-canvas') : __('WooCommerce catalogue mode', 'commerce-canvas')); ?>").replace('@@STATUS_BODY@@', "<?php echo esc_html($is_sample ? __('The theme is showing bundled fictional fixtures. No checkout or payment action is supplied by this sample homepage.', 'commerce-canvas') : __('This homepage presents visible products and links to their WooCommerce pages. Cart, checkout, taxes, shipping and payment gateways remain WooCommerce and merchant configuration responsibilities.', 'commerce-canvas')); ?>")
